using Npgsql;
using PGMS.PostgreSql;

internal static class TableDesignChecks
{
    internal static async Task RunAsync(string connection, Action<bool, string> check)
    {
        string schema = "design_" + Guid.NewGuid().ToString("N")[..8];
        await using var admin = new NpgsqlConnection(connection);
        await admin.OpenAsync();
        async Task Sql(string sql) { await using var command = new NpgsqlCommand(sql, admin); await command.ExecuteNonQueryAsync(); }
        async Task<object?> Scalar(string sql) { await using var command = new NpgsqlCommand(sql, admin); return await command.ExecuteScalarAsync(); }
        var designs = new TableDesignService(connection);
        var edits = new AdministrativeEditService(connection);
        async Task<string?> Refused(Func<Task> action) { try { await action(); return null; } catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or PostgresException) { return ex.Message; } }
        try
        {
            await Sql($"""
                CREATE SCHEMA {schema};
                CREATE TABLE {schema}.parent (id integer PRIMARY KEY, code text UNIQUE);
                CREATE TABLE {schema}.items (
                    id integer GENERATED BY DEFAULT AS IDENTITY,
                    label varchar(80) NOT NULL DEFAULT 'none',
                    amount numeric(10,2),
                    title text COLLATE "C",
                    doubled numeric GENERATED ALWAYS AS (amount * 2) STORED,
                    parent_id integer,
                    CONSTRAINT items_pk PRIMARY KEY (id),
                    CONSTRAINT items_parent FOREIGN KEY (parent_id) REFERENCES {schema}.parent(id) ON DELETE CASCADE,
                    CONSTRAINT items_deferred FOREIGN KEY (parent_id) REFERENCES {schema}.parent(id) DEFERRABLE
                );
                ALTER TABLE {schema}.items ADD CONSTRAINT items_amount CHECK (amount > 0) NOT VALID;
                CREATE INDEX items_label ON {schema}.items (label DESC, amount);
                CREATE INDEX items_lower ON {schema}.items (lower(label));
                CREATE UNIQUE INDEX items_partial ON {schema}.items (label) WHERE amount > 0;
                COMMENT ON TABLE {schema}.items IS 'Items table';
                COMMENT ON COLUMN {schema}.items.label IS 'Shown label';
                COMMENT ON CONSTRAINT items_pk ON {schema}.items IS 'Key note';
                INSERT INTO {schema}.parent VALUES (1,'a');
                INSERT INTO {schema}.items (label, amount, parent_id) VALUES ('first', 1.5, 1), ('second', 2.5, 1);
                """);

            // Reading.
            var design = await designs.InspectAsync(schema, "items");
            var label = design.Columns.Single(c => c.Name == "label");
            check(design.Columns.Select(c => c.Name).SequenceEqual(["id", "label", "amount", "title", "doubled", "parent_id"]) && design.ReadOnlyReason is null && design.Comment == "Items table", "Designer reads the columns in table order");
            check(label.Type == "character varying(80)" && !label.Nullable && label.Default == "'none'::character varying" && label.Comment == "Shown label", "Designer reads type, nullability, default and description");
            check(design.Columns[0].Identity == ColumnIdentity.ByDefault && design.Columns[0].Default is null, "Designer reads identity columns");
            check(design.Columns[4].Generated == "(amount * (2)::numeric)" && design.Columns[3].Collation == "pg_catalog.\"C\"" && design.Columns[2].Collation is null, "Designer reads generated expressions and non-default collations only");
            var pk = design.Indexes.Single(i => i.Kind == DesignIndexKind.PrimaryKey);
            check(pk.Name == "items_pk" && pk.ConstraintBacked && pk.Columns.Single().Name == "id" && pk.Comment == "Key note" && pk.FixedDefinition is null, "Designer reads the primary key with its comment");
            var labelIndex = design.Indexes.Single(i => i.Name == "items_label");
            check(labelIndex.Kind == DesignIndexKind.Index && !labelIndex.ConstraintBacked && labelIndex.Columns.SequenceEqual([new DesignIndexColumn("label", true), new DesignIndexColumn("amount")]) && labelIndex.FixedDefinition is null, "Designer reads index columns and sort order");
            check(design.Indexes.Single(i => i.Name == "items_lower").FixedDefinition is not null && design.Indexes.Single(i => i.Name == "items_partial").FixedDefinition is not null, "Expression and partial indexes are shown as fixed definitions");
            var fk = design.ForeignKeys.Single(f => f.Name == "items_parent");
            check(fk.Columns.Single() == "parent_id" && fk.ReferencedTable == "parent" && fk.ReferencedColumns.Single() == "id" && fk.OnDelete == ReferentialAction.Cascade && fk.OnUpdate == ReferentialAction.NoAction && fk.CheckExisting && fk.FixedDefinition is null, "Designer reads foreign keys with their actions");
            check(design.ForeignKeys.Single(f => f.Name == "items_deferred").FixedDefinition is not null, "A DEFERRABLE foreign key is a fixed definition");
            var amountCheck = design.Checks.Single();
            check(amountCheck.Expression == "(amount > (0)::numeric)" && !amountCheck.CheckExisting, "Designer reads CHECK expressions and NOT VALID");
            check((await designs.InspectAsync(schema, "items")).Fingerprint == design.Fingerprint, "Two reads of an unchanged table have the same fingerprint");
            check(TableDesignScript.Build(design, design).Statements.Count == 0, "An unchanged design produces no statements");

            // Column changes in one transaction.
            var changed = design with
            {
                Comment = "New note",
                Columns = [
                    design.Columns[0],
                    label with { Name = "caption", Type = "text", Nullable = true, Default = "'x'", Comment = null },
                    design.Columns[2] with { Type = "numeric(12,3)" },
                    design.Columns[3] with { Collation = null },
                    design.Columns[5],
                    new DesignColumn(null, "created", "timestamp with time zone", false) { Default = "now()", Comment = "When" }
                ],
                Indexes = design.Indexes.Select(i => i.Name == "items_label" ? i with { Columns = [new("caption", true), new("amount")] } : i).ToArray()
            };
            var change = TableDesignScript.Build(design, changed);
            check(change.Statements.Any(s => s.Contains("DROP COLUMN \"doubled\" RESTRICT")) && change.Statements.Any(s => s.Contains("RENAME COLUMN \"label\" TO \"caption\"")) && change.Statements.Any(s => s.Contains("TYPE numeric(12,3) USING \"amount\"::numeric(12,3)")), "Script drops, renames and retypes columns");
            check(!change.Statements.Any(s => s.Contains("items_label")), "Renaming a column does not rebuild an index that uses it");
            check(change.Warnings.Any(w => w.Contains("doubled")) && change.Warnings.Any(w => w.Contains("amount")), "Script warns about dropped data and converted values");
            await edits.ApplyAsync(new TableDesignEdit(design, changed));
            var saved = await designs.InspectAsync(schema, "items");
            check(saved.Oid == design.Oid && saved.Columns.Select(c => c.Name).SequenceEqual(["id", "caption", "amount", "title", "parent_id", "created"]), "Saving keeps the table identity and applies the column list");
            check((long)(await Scalar($"SELECT count(*) FROM {schema}.items WHERE caption IN ('first','second') AND created IS NOT NULL"))! == 2, "Saving preserves rows and fills the new column");
            var caption = saved.Columns[1];
            check(caption.Type == "text" && caption.Nullable && caption.Default == "'x'::text" && caption.Comment is null && saved.Columns[5].Comment == "When" && saved.Comment == "New note", "Saved columns have the designed type, default, nullability and descriptions");
            check(saved.Columns[3].Collation is null, "Removing a collation returns the column to the default");

            // Primary key, keys, checks and foreign keys.
            var keyed = saved with
            {
                Indexes = [.. saved.Indexes.Where(i => i.Kind != DesignIndexKind.PrimaryKey && i.Name != "items_label"), new DesignIndex(null, "items_new_pk", DesignIndexKind.PrimaryKey, [new("id"), new("created")]) { Comment = "Second key" }, new DesignIndex(null, "items_code", DesignIndexKind.UniqueKey, [new("caption")]), new DesignIndex(null, "items_amount_idx", DesignIndexKind.Index, [new("amount", true)])],
                ForeignKeys = saved.ForeignKeys.Select(f => f.Name == "items_parent" ? f with { OnDelete = ReferentialAction.SetNull } : f).ToArray(),
                Checks = [saved.Checks.Single() with { Name = "items_amount_positive" }, new DesignCheck(null, "items_caption", "caption <> ''")]
            };
            await edits.ApplyAsync(new TableDesignEdit(saved, keyed));
            var rekeyed = await designs.InspectAsync(schema, "items");
            check(rekeyed.Indexes.Single(i => i.Kind == DesignIndexKind.PrimaryKey) is { Name: "items_new_pk", Comment: "Second key" } newKey && newKey.Columns.Select(c => c.Name).SequenceEqual(["id", "created"]), "Changing the primary key replaces it and keeps its comment");
            check(rekeyed.Indexes.Any(i => i is { Name: "items_code", Kind: DesignIndexKind.UniqueKey }) && rekeyed.Indexes.Single(i => i.Name == "items_amount_idx").Columns.Single().Descending && !rekeyed.Indexes.Any(i => i.Name == "items_label"), "Keys and indexes are added and dropped");
            check(rekeyed.ForeignKeys.Single(f => f.Name == "items_parent").OnDelete == ReferentialAction.SetNull, "Changing a foreign key action rebuilds it");
            check(rekeyed.Checks.Select(c => c.Name).OrderBy(n => n).SequenceEqual(["items_amount_positive", "items_caption"]) && !rekeyed.Checks.Single(c => c.Name == "items_amount_positive").CheckExisting, "A CHECK rename keeps it NOT VALID, and new checks are added");
            string? refusedRow = await Refused(() => Sql($"INSERT INTO {schema}.items (caption, amount, parent_id) VALUES ('', 1, 1)"));
            check(refusedRow?.Contains("items_caption") == true, "The new CHECK is enforced");

            // Identity and table rename.
            var plain = rekeyed with { Name = "renamed", Columns = rekeyed.Columns.Select(c => c.Name == "id" ? c with { Identity = ColumnIdentity.Always } : c).ToArray() };
            await edits.ApplyAsync(new TableDesignEdit(rekeyed, plain));
            var renamed = await designs.InspectAsync(schema, "renamed");
            check(renamed.Oid == rekeyed.Oid && renamed.Columns[0].Identity == ColumnIdentity.Always, "Table rename and identity mode are applied together");
            var noIdentity = renamed with { Columns = renamed.Columns.Select(c => c.Name == "id" ? c with { Identity = ColumnIdentity.None } : c).ToArray() };
            await edits.ApplyAsync(new TableDesignEdit(renamed, noIdentity));
            check((await designs.InspectAsync(schema, "renamed")).Columns[0].Identity == ColumnIdentity.None, "Identity can be removed");

            // Refusals.
            var current = await designs.InspectAsync(schema, "renamed");
            await Sql($"ALTER TABLE {schema}.renamed ADD COLUMN outside integer");
            var stale = current with { Columns = [.. current.Columns, new DesignColumn(null, "late", "integer", true)] };
            string? staleError = await Refused(() => edits.ApplyAsync(new TableDesignEdit(current, stale)));
            check(staleError?.Contains("changed since the designer read it") == true && !(await designs.InspectAsync(schema, "renamed")).Columns.Any(c => c.Name == "late"), "A table changed by someone else is not saved over");
            current = await designs.InspectAsync(schema, "renamed");
            var failing = current with { Columns = [.. current.Columns.Select(c => c.Name == "caption" ? c with { Name = "label2" } : c), new DesignColumn(null, "required", "integer", false)] };
            string? failure = await Refused(() => edits.ApplyAsync(new TableDesignEdit(current, failing)));
            var after = await designs.InspectAsync(schema, "renamed");
            check(failure is not null && after.Columns.Any(c => c.Name == "caption") && !after.Columns.Any(c => c.Name == "label2"), "A failing statement rolls back the whole save");
            var parent = await designs.InspectAsync(schema, "parent");
            string? referenced = await Refused(() => edits.ApplyAsync(new TableDesignEdit(parent, parent with { Indexes = parent.Indexes.Where(i => i.Kind != DesignIndexKind.PrimaryKey).ToArray() })));
            check(referenced is not null && (await designs.InspectAsync(schema, "parent")).Indexes.Any(i => i.Kind == DesignIndexKind.PrimaryKey), "A primary key used by a foreign key is not dropped silently");

            string? Invalid(TableDesign candidate) { try { TableDesignScript.Build(current, candidate); return null; } catch (ArgumentException ex) { return ex.Message; } }
            var first = current.Columns[1];
            DesignColumn[] With(DesignColumn column) => current.Columns.Select(c => c.Position == column.Position ? column : c).ToArray();
            check(Invalid(current with { Columns = With(first with { Type = "int); DROP TABLE x" }) }) is not null, "A type with statement text is refused");
            check(Invalid(current with { Columns = With(first with { Default = "1; DROP TABLE x" }) }) is not null, "A default with a statement terminator is refused");
            check(Invalid(current with { Columns = With(first with { Name = current.Columns[0].Name }) })?.Contains("more than once") == true, "Duplicate column names are refused");
            check(Invalid(current with { Columns = With(first with { Identity = ColumnIdentity.Always }) })?.Contains("identity") == true, "Identity on a text column is refused");
            check(Invalid(current with { Columns = With(first with { Generated = "1" }) })?.Contains("generated") == true, "A generated expression on an existing column is refused");
            check(Invalid(current with { Columns = [] }) is not null, "A table without columns is refused");
            var a = current.Columns[1]; var b = current.Columns[2];
            check(Invalid(current with { Columns = current.Columns.Select(c => c.Position == a.Position ? c with { Name = b.Name } : c.Position == b.Position ? c with { Name = a.Name } : c).ToArray() })?.Contains("renames separately") == true, "Swapping two column names asks for separate saves");
            check(Invalid(current with { Checks = [new DesignCheck(null, "x", "1=1; DROP TABLE y")] }) is not null, "A CHECK with a statement terminator is refused");
            check(Invalid(current with { Indexes = [.. current.Indexes, new DesignIndex(null, "nope", DesignIndexKind.Index, [new("missing")])] })?.Contains("missing") == true, "An index on an unknown column is refused");
            check(Invalid(current with { ForeignKeys = [new DesignForeignKey(null, "bad", ["id"], schema, "parent", ["id", "code"])] }) is not null, "A foreign key with unequal column counts is refused");

            // New table.
            var created = new TableDesign(0, schema, "fresh \"one\"", [new DesignColumn(null, "id", "bigint", false) { Identity = ColumnIdentity.Always, Comment = "Key" }, new DesignColumn(null, "name", "character varying(20)", true) { Default = "'n'" }, new DesignColumn(null, "total", "integer", true) { Generated = "id * 2" }])
            {
                Comment = "Fresh", Indexes = [new DesignIndex(null, "fresh_pk", DesignIndexKind.PrimaryKey, [new("id")])], Checks = [new DesignCheck(null, "fresh_ck", "name <> ''")],
                ForeignKeys = [new DesignForeignKey(null, "fresh_fk", ["id"], schema, "parent", ["id"]) { CheckExisting = false }]
            };
            check(TableDesignScript.Build(null, created).Statements[0].StartsWith("CREATE TABLE", StringComparison.Ordinal), "A new table starts with CREATE TABLE");
            await edits.ApplyAsync(new TableDesignEdit(null, created));
            var fresh = await designs.InspectAsync(schema, "fresh \"one\"");
            check(fresh.Columns.Count == 3 && fresh.Comment == "Fresh" && fresh.Columns[0] is { Identity: ColumnIdentity.Always, Comment: "Key" } && fresh.Columns[2].Generated is not null && fresh.Indexes.Single().Name == "fresh_pk" && fresh.Checks.Count == 1 && !fresh.ForeignKeys.Single().CheckExisting, "A new table is created with its keys, constraints and descriptions");

            // Tables the designer does not change.
            await Sql($"""
                CREATE TABLE {schema}.sales (at date, v int) PARTITION BY RANGE (at);
                CREATE TABLE {schema}.sales_a PARTITION OF {schema}.sales FOR VALUES FROM ('2020-01-01') TO ('2021-01-01');
                CREATE TABLE {schema}.base (id int); CREATE TABLE {schema}.derived () INHERITS ({schema}.base);
                """);
            check((await designs.InspectAsync(schema, "sales")).ReadOnlyReason is not null && (await designs.InspectAsync(schema, "sales_a")).ReadOnlyReason is not null && (await designs.InspectAsync(schema, "base")).ReadOnlyReason is not null, "Partitioned, partition and inherited tables open read-only");
            check(await Refused(() => designs.InspectAsync(schema, "missing")) is not null, "A missing table is reported");
        }
        finally { await Sql($"DROP SCHEMA IF EXISTS {schema} CASCADE"); }
    }
}
